package com.smarthub.plus;
import android.content.Context;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.json.*;
/** Direct TMDB search/details with cache keys that never contain credentials. */
final class TmdbProvider {
 private final Context context;private final String key;private boolean cached,validating;private long fetchedAt=System.currentTimeMillis();
 TmdbProvider(Context c,String key){context=c.getApplicationContext();this.key=key.trim();}
 private static String enc(String s)throws Exception{return URLEncoder.encode(s,"UTF-8");}
 private JSONObject request(String route)throws Exception{
  if(!PosterSourceSwitches.enabled(context,PosterSourceSwitches.TMDB))
   throw new IOException("TMDB_DISABLED");File dir=new File(context.getCacheDir(),"tmdb-metadata");dir.mkdirs();String hash;{byte[] digest=java.security.MessageDigest.getInstance("SHA-256").digest(route.getBytes(StandardCharsets.UTF_8));StringBuilder b=new StringBuilder();for(byte v:digest)b.append(String.format(Locale.ROOT,"%02x",v&255));hash=b.toString();}File file=new File(dir,hash+".json");JSONObject old=null;if(file.isFile())try(InputStream in=new FileInputStream(file)){old=new JSONObject(PlaylistRepository.readBounded(in));}catch(Exception ignored){}if(!validating&&old!=null&&System.currentTimeMillis()-old.optLong("at")<300000)return old.getJSONObject("data");
  Map<String,String> headers=new HashMap<>();headers.put("Accept","application/json");String url="https://api.themoviedb.org/3/"+route;if(key.matches("[a-fA-F0-9]{32}"))url+=(route.contains("?")?"&":"?")+"api_key="+enc(key);else headers.put("Authorization","Bearer "+key);
  try{DirectHttp.Reply r=DirectHttp.request(url,headers,null,3*1024*1024,null);if(r.code!=200)throw new IOException("TMDB HTTP "+r.code);JSONObject data=new JSONObject(new String(r.bytes,StandardCharsets.UTF_8));try(FileOutputStream out=new FileOutputStream(file)){out.write(new JSONObject().put("at",System.currentTimeMillis()).put("data",data).toString().getBytes(StandardCharsets.UTF_8));}File[] all=dir.listFiles();if(all!=null&&all.length>100){Arrays.sort(all,Comparator.comparingLong(File::lastModified));for(int n=0;n<all.length-100;n++)all[n].delete();}return data;}catch(Exception e){if(!validating&&old!=null){cached=true;fetchedAt=Math.min(fetchedAt,old.optLong("at"));return old.getJSONObject("data");}String message=e.getMessage();throw new IOException(message!=null&&message.matches("TMDB HTTP [0-9]+")?message:"TMDB connection failed ("+e.getClass().getSimpleName()+")");}}
 void validate()throws Exception{validating=true;try{JSONObject c=request("configuration");if(c.optJSONObject("images")==null)throw new IOException("Invalid TMDB configuration response");}finally{validating=false;}}
 private String lang(){return context.getSharedPreferences("smarthub",0).getBoolean("arabic",true)?"ar-SA":"en-US";}
 static String image(String path){return path!=null&&path.matches("/[A-Za-z0-9._-]+")?"https://image.tmdb.org/t/p/w780"+path:"";}
 private static int year(String text){java.util.regex.Matcher m=java.util.regex.Pattern.compile("^(?:19|20)[0-9]{2}").matcher(text);return m.find()?Integer.parseInt(m.group()):0;}
 private JSONObject details(String type,int id,String expectedImdb)throws Exception{String kind=type.equals("series")?"tv":"movie";JSONObject d=request(kind+"/"+id+"?language="+lang()+"&append_to_response=credits,external_ids,images,alternative_titles&include_image_language=ar,en,null");if(d.optInt("id")!=id)throw new IOException("TMDB identity mismatch");String imdb=d.optString("imdb_id");JSONObject external=d.optJSONObject("external_ids");if(imdb.isEmpty()&&external!=null)imdb=external.optString("imdb_id");if(!expectedImdb.isEmpty()&&!expectedImdb.equals(imdb))throw new IOException("TMDB IMDb identity mismatch");if(!imdb.matches("tt[0-9]{7,10}"))imdb="";JSONArray castNames=new JSONArray(),directors=new JSONArray(),people=new JSONArray(),genres=new JSONArray();JSONObject credits=d.optJSONObject("credits");JSONArray cast=credits==null?null:credits.optJSONArray("cast"),crew=credits==null?null:credits.optJSONArray("crew");if(cast!=null)for(int n=0;n<Math.min(8,cast.length());n++){JSONObject p=cast.optJSONObject(n);if(p==null)continue;castNames.put(p.optString("name"));people.put(new JSONObject().put("name",p.optString("name")).put("role",p.optString("character")).put("photo",image(p.optString("profile_path"))).put("source","https://www.themoviedb.org/person/"+p.optInt("id")));}if(crew!=null)for(int n=0;n<crew.length();n++){JSONObject p=crew.optJSONObject(n);if(p!=null&&"Director".equals(p.optString("job")))directors.put(p.optString("name"));}JSONArray g=d.optJSONArray("genres");if(g!=null)for(int n=0;n<g.length();n++)genres.put(g.getJSONObject(n).optString("name"));String title=d.optString(kind.equals("movie")?"title":"name"),date=d.optString(kind.equals("movie")?"release_date":"first_air_date");int minutes=d.optInt("runtime");return new JSONObject().put("status","matched").put("id","tmdb:"+id).put("type",type).put("imdbId",imdb).put("title",title).put("year",year(date)).put("poster",image(d.optString("poster_path"))).put("background",image(d.optString("backdrop_path"))).put("description",d.optString("overview")).put("runtime",minutes>0?minutes+" min":"").put("rating",d.optString("vote_average")).put("cast",castNames).put("directors",directors).put("people",people).put("genres",genres).put("provider","TMDB").put("source","https://www.themoviedb.org/"+kind+"/"+id).put("cached",cached).put("fetchedAt",fetchedAt);}
 JSONObject resolve(String raw,String chosenId,String chosenType,String imdb,double duration)throws Exception{BroadcastTitle wanted=BroadcastTitle.parse(raw);if(chosenId.matches("tmdb:[1-9][0-9]*"))return details(chosenType,Integer.parseInt(chosenId.substring(5)),"");List<JSONObject> candidates=new ArrayList<>(),exact=new ArrayList<>();if(imdb.matches("tt[0-9]{7,10}")){JSONObject found=request("find/"+imdb+"?external_source=imdb_id&language="+lang());for(String[] pair:new String[][]{{"movie_results","movie"},{"tv_results","series"}}){JSONArray a=found.optJSONArray(pair[0]);if(a!=null)for(int n=0;n<a.length();n++)candidates.add(candidate(a.getJSONObject(n),pair[1]));}if(candidates.size()==1){JSONObject c=candidates.get(0);return details(c.getString("type"),c.getInt("numericId"),imdb);}}
  else for(String type:wanted.season>0||wanted.episode>0?new String[]{"series"}:new String[]{"movie","series"}){String kind=type.equals("movie")?"movie":"tv";String route="search/"+kind+"?query="+enc(wanted.title)+"&language="+lang()+"&include_adult=false"+(wanted.year>0?"&"+(kind.equals("movie")?"year":"first_air_date_year")+"="+wanted.year:"");JSONArray a=request(route).optJSONArray("results");if(a==null)throw new IOException("Invalid TMDB search response");for(int n=0;n<Math.min(30,a.length());n++){JSONObject item=a.getJSONObject(n);JSONObject c=candidate(item,type);if(wanted.year>0&&c.optInt("year")!=wanted.year)continue;candidates.add(c);String original=item.optString(kind.equals("movie")?"original_title":"original_name");if(BetterPostersProvider.titleTokens(wanted.title).equals(BetterPostersProvider.titleTokens(c.optString("title")))||BetterPostersProvider.titleTokens(wanted.title).equals(BetterPostersProvider.titleTokens(original)))exact.add(c);}}
  if(exact.isEmpty()&&candidates.size()<=5){for(JSONObject candidate:candidates){String kind=candidate.getString("type").equals("series")?"tv":"movie";JSONObject aliases=request(kind+"/"+candidate.getInt("numericId")+"/alternative_titles");JSONArray titles=aliases.optJSONArray(kind.equals("movie")?"titles":"results");if(titles!=null)for(int n=0;n<titles.length();n++){JSONObject alias=titles.optJSONObject(n);if(alias!=null&&BetterPostersProvider.titleTokens(wanted.title).equals(BetterPostersProvider.titleTokens(alias.optString("title")))){exact.add(candidate);break;}}}}JSONObject newest=ProgrammeChoice.first(exact,wanted.year,wanted.season>0||wanted.episode>0,java.time.LocalDate.now().toString());if(newest!=null)return details(newest.getString("type"),newest.getInt("numericId"),"");return new JSONObject().put("status",candidates.isEmpty()?"not_found":"ambiguous").put("candidates",new JSONArray(exact.isEmpty()?candidates:exact));}
 private static JSONObject candidate(JSONObject j,String type)throws Exception{return new JSONObject().put("id","tmdb:"+j.optInt("id")).put("numericId",j.optInt("id")).put("type",type).put("title",j.optString(type.equals("movie")?"title":"name")).put("year",year(j.optString(type.equals("movie")?"release_date":"first_air_date",j.optString("first_air_date")))).put("releaseDate",j.optString(type.equals("movie")?"release_date":"first_air_date")).put("popularity",j.optDouble("popularity",0)).put("poster",image(j.optString("poster_path")));}
}
